{"source":"#include<stdio.h>

int main(int argc, char *argv[])
{
    int a,b,count=0,i,c;
    scanf("%d %d",&a,&b);
    if(a==b){
        printf("infinity");
        return 0;
    }
    else{
        c=a-b;
        if(c<0) c=-c;
        for(i=1;i*i<=c;i++){
            if(c%i==0&&a%i==b){
            count++;
            }
            if(c%(c/i)==0&&a%(c/i)==b){
            count++;
            }
        }
    }
    printf("%d",count);
    return 0;
}"}
